package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"slices"
	"strings"
)

var tierOrder = []string{
	"A",
	"B",
	"C",
	"unassigned",
}

func writeMatrix(w io.Writer, inv Inventory, covered map[string]bool) error {
	for _, c := range inv.Commands {
		if !slices.Contains(tierOrder, c.Tier) {
			return fmt.Errorf("command %q has tier %q, none of %v", c.Command, c.Tier, tierOrder)
		}
	}

	var b strings.Builder
	fmt.Fprintf(&b, "# Compatibility matrix\n\n")
	fmt.Fprintf(
		&b,
		"Generated by `api/adapters/artifactory/compat/inventory matrix` from `api/adapters/artifactory/compat/docs/commands.yaml` (jf %s) and the\n",
		inv.JFVersion,
	)
	fmt.Fprintf(
		&b,
		"required e2e scenarios (`api/adapters/artifactory/compat/e2e/required.txt`, `# covers:` headers). Do not edit.\n\n",
	)
	fmt.Fprintf(&b, "**E2E** means a required scenario runs the command with the pinned jf against Relic in CI.\n\n")
	fmt.Fprintf(&b, "| Tier | Total | E2E |\n|---|---|---|\n")

	for _, tier := range tierOrder {
		total, e2e := 0, 0

		for _, c := range inv.Commands {
			if c.Tier != tier {
				continue
			}

			total++

			if covered[c.Command] {
				e2e++
			}
		}

		fmt.Fprintf(&b, "| %s | %d | %d |\n", tier, total, e2e)
	}

	for _, tier := range tierOrder {
		cmds := slices.DeleteFunc(slices.Clone(inv.Commands), func(c Command) bool {
			return c.Tier != tier
		})
		if len(cmds) == 0 {
			continue
		}

		fmt.Fprintf(
			&b,
			"\n## Tier %s\n\n| Command | Aliases | Category | Local | E2E |\n|---|---|---|---|---|\n",
			tier,
		)

		for _, c := range cmds {
			name := "`jf " + c.Command + "`"
			if c.Hidden {
				name += " (hidden)"
			}

			e2e := ""
			if covered[c.Command] {
				e2e = "✅"
			}

			fmt.Fprintf(
				&b,
				"| %s | %s | %s | %v | %s |\n",
				name,
				strings.Join(c.Aliases, ", "),
				c.Category,
				c.LocalOnly,
				e2e,
			)
		}
	}

	_, err := io.WriteString(w, b.String())

	return err
}

var suites = map[string]bool{
	"sdk-artifactory-rest": true,
}

func coveredCommands(requiredPath, scenariosDir string) (map[string]bool, error) {
	req, err := os.ReadFile(requiredPath)
	if err != nil {
		return nil, err
	}

	covered := map[string]bool{}

	for line := range strings.Lines(string(req)) {
		name := strings.TrimSpace(line)
		if name == "" || strings.HasPrefix(name, "#") || suites[name] {
			continue
		}

		script, err := os.ReadFile(filepath.Join(scenariosDir, name+".sh"))
		if err != nil {
			return nil, fmt.Errorf("required scenario %s: %w", name, err)
		}

		for l := range strings.Lines(string(script)) {
			if list, ok := strings.CutPrefix(strings.TrimSpace(l), "# covers:"); ok {
				for cmd := range strings.SplitSeq(list, ",") {
					covered[strings.TrimSpace(cmd)] = true
				}
			}
		}
	}

	return covered, nil
}
